// paragraph breaks (double newlines become an empty line).
func wrapText(s string, width int) []string {
	if width <= 0 {
		return []string{s}
	}
	var out []string
	for paragraph := range strings.SplitSeq(s, "\n") {
		if paragraph == "" {
			out = append(out, "")
			continue
		}
